def _is_same_type_date(day1, day2, frequency):
    if frequency == '1w':
        a = day1.isocalendar()
        b = day2.isocalendar()
        if a[0] == b[0] and a[1] == b[1]:
            return True
        return False
    elif frequency == 'mo':
        if day1.year == day2.year and day1.month == day2.month:
            return True
        else:
            return False
    elif frequency == '1y':
        if day1.year == day2.year:
            return True
        else:
            return False
    elif frequency == '1q':
        if day1.year == day2.year and (day1.month - 1) // 3 == (day2.month - 1) // 3:
            return True
        else:
            return False
