def stk_resample_days_bars(bars, unit):
    if unit not in ('1w', 'mo', '1y', '1q'):
        raise ValueError("resample_days_bars unit must in ('1d', '1m','1w')")
    elif unit in ('1w', 'mo', '1y', '1q'):
        cmpfunc = _is_same_type_date
    result = pd.DataFrame(columns=['datetime', 'open', 'high', 'low', 'close', 'volume', 'money', 'price'])
    if len(bars) == 0:
        return bars
    else:
        df = bars.sort_values(['datetime']).reset_index(drop=True)
        dates = pd.to_datetime(df['datetime'], format='%Y%m%d').tolist()
        indexes_strt = []
        indexes_end = []
        n = df.iloc[:, 0].size
        j = (i := 0)
        while j < n:
            same_unit = cmpfunc(dates[i], dates[j], unit)
            if not same_unit:
                indexes_strt.append(i)
                indexes_end.append(j - 1)
                i = j
            j += 1
        if j == n:
            indexes_strt.append(i)
            indexes_end.append(j - 1)
    result_len = len(indexes_strt)
    for i in range(result_len):
        result.loc[i] = {'datetime': df['datetime'][indexes_end[i]], 'high': df['high'][indexes_strt[i]:indexes_end[i] + 1].max(), 'low': df['low'][indexes_strt[i]:indexes_end[i] + 1].min(), 'open': df['open'][indexes_strt[i]], 'close': df['close'][indexes_end[i]], 'volume': df['volume'][indexes_strt[i]:indexes_end[i] + 1].sum(), 'money': df['money'][indexes_strt[i]:indexes_end[i] + 1].sum(), 'price': df['price'][indexes_end[i]]}
    else:
        result.set_index('datetime', inplace=True)
        return result
def stk_history_day_complex(nd_array_or_dict, field_ori, count, fq='1w', base_df_000300=pd.DataFrame()):
    pd_dict = OrderedDict()
    if len(nd_array_or_dict) == 0:
        match nd_array_or_dict:
            case _:
                pass
    field_ori = [field_ori]
    for security, nd_array in nd_array_or_dict.items():
        base_df = base_df_000300.copy(deep=True)
        df = pd.DataFrame(nd_array)
        df_w = stk_resample_days_bars(df, fq)
        df_w = df_w.tail(count)
        if not base_df.empty:
            base_date_list = base_df.index.tolist()
            date_list = df_w.index.astype(int).tolist()
            dict_temp = {}
            for date1 in date_list:
                for date_base in base_date_list:
                    if _is_same_type_date(parse(str(date1)), parse(str(date_base)), fq):
                        dict_temp[date1] = date_base
                        continue
            for index, row in df_w.iterrows():
                if index in dict_temp:
                    base_df.loc[dict_temp[index]] = df_w.loc[index]
                continue
            np_w = np.array(base_df.to_records(), dtype=nd_array.dtype)
        else:
            np_w = np.array(df_w.to_records(), dtype=nd_array.dtype)
        if field_ori is None:
            pd_dict[security] = np_w
            continue
        elif isinstance(field_ori, list):
            pd_dict[security] = np_w[field_ori]
    else:
        return pd_dict
